CREATE TABLE authors (
	id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	name          text NOT NULL,
	email         text UNIQUE,
	password_hash text NOT NULL DEFAULT 'unset',
	bio           text
);

CREATE TYPE post_status AS ENUM ('draft', 'published');

CREATE TABLE posts (
	id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	author_id    integer NOT NULL REFERENCES authors (id) ON DELETE CASCADE,
	title        text NOT NULL,
	status       post_status NOT NULL DEFAULT 'draft',
	views        integer NOT NULL DEFAULT 0 CHECK (views >= 0),
	published_on date
);

CREATE TABLE comments (
	id      serial PRIMARY KEY,
	post_id integer NOT NULL REFERENCES posts (id) ON DELETE RESTRICT,
	body    text NOT NULL
);

CREATE TABLE post_tags (
	post_id integer NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
	tag     text NOT NULL,
	PRIMARY KEY (post_id, tag)
);

CREATE TABLE "weird ""table"" <b>x</b>" (
	"id"                        serial PRIMARY KEY,
	"col with space"            text,
	"<script>alert(1)</script>" text,
	"semi;colon--"              text
);

CREATE TYPE mood AS ENUM ('sad', 'ok', 'happy');

CREATE TABLE kinds (
	id             integer PRIMARY KEY,
	k_varchar      varchar(40),
	k_text         text,
	k_int          integer,
	k_bigint       bigint,
	k_float        double precision,
	k_real         real,
	k_decimal      numeric(12, 4),
	k_bool         boolean,
	k_date         date,
	k_time         time,
	k_timestamp    timestamp,
	k_timestamptz  timestamptz,
	k_json         json,
	k_jsonb        jsonb,
	k_uuid         uuid,
	k_bytes        bytea,
	k_enum         mood,
	k_array        integer[],
	k_inet         inet,
	k_char         char(5),
	k_secret_token text
);

